@using sv_ffeefcb04b4d4189bd8f291e0a23624f.Services
@inject WarehouseState Warehouse
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" value="@Warehouse.SelectedWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 220px;">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        Warehouse.SetWarehouse(e.Value?.ToString() ?? "");
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        Warehouse.OnChange -= OnStateChanged;
    }
}

@using sv_ffeefcb04b4d4189bd8f291e0a23624f.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.CurrentLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentLowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnAlertCountChanged -= _handler;
    }
}

@page "/dashboard"
@using sv_ffeefcb04b4d4189bd8f291e0a23624f.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @Warehouse.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@Warehouse.SelectedWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="text-danger fs-3 fw-bold">@AlertService.CurrentLowStockCount</span>
                <span class="text-muted ms-2">items below minimum levels</span>
            }
            else
            {
                <span class="text-success fs-3 fw-bold">0</span>
                <span class="text-muted ms-2">all stock levels OK</span>
            }
        </p>
        <small class="text-muted">
            @if (_lastChecked is not null)
            {
                <text>Last checked: @_lastChecked.Value.ToString("HH:mm:ss")</text>
            }
            else
            {
                <text>Checking...</text>
            }
            &nbsp;· Polling every 10 seconds
        </small>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes so we re-poll immediately on switch.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await PollAlerts();
            StateHasChanged();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Subscribe to alert changes so this page re-renders when count updates.
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial poll, then start periodic polling.
        await PollAlerts();
        _cts = new CancellationTokenSource();
        _ = PollLoop(_cts.Token);
    }

    private async Task PollLoop(CancellationToken ct)
    {
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await _timer.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await PollAlerts();
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(Warehouse.SelectedWarehouseId);
        _lastChecked = DateTime.Now;
        // Updates cached count and notifies ALL subscribers (sidebar badge, etc.).
        AlertService.UpdateCount(count);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

